// Real-time Legal Search with WebSocket/NATS Integration
// Optimized for Svelte 5 and SvelteKit 2 with bits-ui components
import { writable, derived, type Writable } from 'svelte/store';

// WebSocket Service Registry Interface
interface WSRegistryEntry {
  name: string;
  uuid: string;
  port: number;
  endpoint: string;
}

// Load WebSocket service registry (auto-generated by ws-orchestrator)
let wsRegistry: WSRegistryEntry[] = [];
try {
  // Try to import the auto-generated registry
  wsRegistry = await import('../../../.ws-registry.json').then(m => m.default || []);
} catch (error) {
  console.warn('⚠️ WebSocket registry not found, falling back to environment variables');
}

// Enhanced RAG Service Configuration with auto-discovery
function getEnhancedRAGConfig() {
  // Try registry first
  const registryEntry = wsRegistry.find(s => s.name === 'enhanced-rag');
  if (registryEntry) {
    return {
      wsUrl: `ws://localhost:${registryEntry.port}${registryEntry.endpoint}`,
      httpUrl: `http://localhost:${registryEntry.port}`,
      source: 'registry',
    };
  }

  // Fallback to environment variables
  const envPort = import.meta.env.VITE_WS_enhanced_rag_PORT;
  const envUUID = import.meta.env.VITE_WS_enhanced_rag_UUID;
  if (envPort && envUUID) {
    return {
      wsUrl: `ws://localhost:${envPort}/ws/${envUUID}`,
      httpUrl: `http://localhost:${envPort}`,
      source: 'env',
    };
  }

  // Final fallback to hardcoded values
  console.warn('⚠️ No registry or env config found, using fallback port 8094');
  return {
    wsUrl: 'ws://localhost:8094/ws/legal-search-client',
    httpUrl: 'http://localhost:8094',
    source: 'fallback',
  };
}

const RAG_CONFIG = getEnhancedRAGConfig();
console.log(`🔌 Enhanced RAG config loaded from: ${RAG_CONFIG.source}`, RAG_CONFIG);

const ENHANCED_RAG_URL = RAG_CONFIG.httpUrl;
const UPLOAD_SERVICE_URL = 'http://localhost:8093';
const NATS_WS_URL = 'ws://localhost:4222';

// Real-time search state management
export interface RealTimeSearchState {
  isConnected: boolean;
  isSearching: boolean;
  currentQuery: string;
  results: SearchResult[];
  suggestions: string[];
  error: string | null;
  connectionStatus: 'disconnected' | 'connecting' | 'connected' | 'error';
  searchMetrics: {
    totalQueries: number;
    averageResponseTime: number;
    lastQueryTime: number;
  };
}

export interface SearchResult {
  id: string;
  title: string;
  type: 'case' | 'evidence' | 'precedent' | 'statute' | 'criminal' | 'document';
  content: string;
  score: number;
  similarity?: number;
  metadata: {
    date?: string;
    jurisdiction?: string;
    status?: string;
    confidentiality?: string;
    caseId?: string;
    tags?: string[];
  };
  highlights?: string[];
  createdAt?: string;
  realTime?: boolean;
}

// Enhanced Real-time Search Service
export class RealTimeSearchService {
  private ws: WebSocket | null = null;
  private natsConnection: any = null;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private reconnectInterval = 2000;
  private searchQueue: Array<any> = [];
  private isProcessingQueue = false;

  // Reactive stores for Svelte 5 compatibility
  public state: Writable<RealTimeSearchState> = writable({
    isConnected: false,
    isSearching: false,
    currentQuery: '',
    results: [],
    suggestions: [],
    error: null,
    connectionStatus: 'disconnected',
    searchMetrics: {
      totalQueries: 0,
      averageResponseTime: 0,
      lastQueryTime: 0,
    },
  });

  // Derived stores for enhanced UX
  public isReady = derived(this.state, $state => $state.isConnected && !$state.isSearching);
  public hasResults = derived(this.state, $state => $state.results.length > 0);
  public searchStatus = derived(this.state, $state => {
    if ($state.isSearching) return 'searching';
    if ($state.error) return 'error';
    if ($state.results.length > 0) return 'results';
    return 'idle';
  });

  constructor() {
    this.initializeConnections();
  }

  // Initialize WebSocket and NATS connections
  private async initializeConnections(): Promise<void> {
    try {
      this.state.update(s => ({ ...s, connectionStatus: 'connecting' }));

      // Initialize WebSocket connection to Enhanced RAG service
      try {
        await this.connectWebSocket();
        console.log('✅ WebSocket connection established');
      } catch (wsError) {
        console.warn('⚠️ WebSocket connection failed, falling back to HTTP-only mode:', wsError);
        // Don't throw - allow the service to work with HTTP fallback
      }

      // Initialize NATS connection for real-time messaging
      try {
        await this.connectNATS();
      } catch (natsError) {
        console.warn('⚠️ NATS connection failed:', natsError);
        // NATS is optional - continue without it
      }

      // Update state based on connection status
      const isConnected = this.ws?.readyState === WebSocket.OPEN;
      this.state.update(s => ({
        ...s,
        isConnected,
        connectionStatus: isConnected ? 'connected' : 'error',
        error: isConnected ? null : 'Using HTTP-only search (real-time unavailable)',
      }));

      if (isConnected) {
        console.log('🔗 Real-time search connections established');
      } else {
        console.log('📡 Real-time search running in HTTP-only mode');
      }
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      console.error('❌ Failed to initialize real-time search:', error);
      this.state.update(s => ({
        ...s,
        error: `Connection failed: ${errorMessage}`,
        connectionStatus: 'error',
        isConnected: false,
      }));
      // Don't attempt reconnection for initialization failures
    }
  }

  // WebSocket connection to Enhanced RAG service
  private async connectWebSocket(): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        // Close existing connection if any
        if (this.ws) {
          this.ws.onclose = null;
          this.ws.onerror = null;
          this.ws.close();
          this.ws = null;
        }

        // Check if we've exceeded max reconnection attempts
        if (this.reconnectAttempts >= this.maxReconnectAttempts) {
          console.warn('⚠️ Max WebSocket reconnection attempts reached. Using HTTP fallback.');
          this.state.update(s => ({
            ...s,
            isConnected: false,
            connectionStatus: 'error',
            error: 'WebSocket unavailable - using HTTP fallback',
          }));
          reject(new Error('Max reconnection attempts exceeded'));
          return;
        }

        // Use the WebSocket endpoint from auto-discovery config
        console.log(
          `🔄 Attempting WebSocket connection (attempt ${this.reconnectAttempts + 1}/${this.maxReconnectAttempts})...`
        );
        console.log(`🔌 Connecting to: ${RAG_CONFIG.wsUrl}`);
        this.ws = new WebSocket(RAG_CONFIG.wsUrl);

        this.ws.onopen = () => {
          console.log('🚀 WebSocket connected to Enhanced RAG service');
          this.reconnectAttempts = 0;
          resolve();
        };

        this.ws.onmessage = (event: any) => {
          this.handleWebSocketMessage(event);
        };

        this.ws.onclose = event => {
          console.log(
            `🔌 WebSocket disconnected (code: ${event.code}, reason: ${event.reason || 'No reason provided'})`
          );
          this.state.update(s => ({ ...s, isConnected: false, connectionStatus: 'disconnected' }));

          // Only schedule reconnection if not a normal close
          if (event.code !== 1000) {
            this.scheduleReconnection();
          }
        };

        this.ws.onerror = error => {
          console.error('❌ WebSocket error:', error);
          // Don't reject immediately - let onclose handle reconnection
          this.state.update(s => ({
            ...s,
            connectionStatus: 'error',
            error: 'WebSocket connection failed - retrying or using HTTP fallback',
          }));
        };

        // Timeout after 5 seconds
        const timeoutId = setTimeout(() => {
          if (this.ws?.readyState !== WebSocket.OPEN) {
            console.warn('⏱️ WebSocket connection timeout');
            this.ws?.close();
            reject(new Error('WebSocket connection timeout'));
          }
        }, 5000);

        // Clear timeout on successful connection
        this.ws.addEventListener(
          'open',
          () => {
            clearTimeout(timeoutId);
          },
          { once: true }
        );
      } catch (error: any) {
        console.error('❌ WebSocket connection error:', error);
        reject(error);
      }
    });
  }

  // NATS connection for distributed messaging
  private async connectNATS(): Promise<void> {
    try {
      // Use a lightweight NATS client for browser
      // Since we're in a browser environment, we'll use WebSocket-based NATS
      console.log('📡 Connecting to NATS via WebSocket...');
      // For now, we'll focus on WebSocket and add full NATS later
      // This allows immediate testing with the existing Enhanced RAG WebSocket
    } catch (error: any) {
      console.warn('⚠️ NATS connection failed, using WebSocket only:', error);
    }
  }

  // Handle WebSocket messages from Enhanced RAG service
  private handleWebSocketMessage(event: MessageEvent): void {
    try {
      const message = JSON.parse(event.data);
      switch (message.type) {
        case 'search_results':
          this.handleSearchResults(message.data);
          break;
        case 'search_suggestions':
          this.handleSearchSuggestions(message.data);
          break;
        case 'search_progress':
          this.handleSearchProgress(message.data);
          break;
        case 'error':
          this.handleSearchError(message.data);
          break;
        default:
          console.log('📨 Received WebSocket message:', message);
      }
    } catch (error: any) {
      console.error('❌ Failed to parse WebSocket message:', error);
    }
  }

  // Real-time search with streaming results
  public async performRealTimeSearch(
    query: string,
    options: {
      categories?: string[];
      vectorSearch?: boolean;
      streamResults?: boolean;
      includeAI?: boolean;
    } = {}
  ): Promise<SearchResult[]> {
    const startTime = Date.now();
    this.state.update(s => ({
      ...s,
      isSearching: true,
      currentQuery: query,
      error: null,
    }));
    try {
      // If WebSocket is available, use real-time streaming
      if (this.ws?.readyState === WebSocket.OPEN && options.streamResults !== false) {
        return await this.performStreamingSearch(query, options);
      }
      // Fallback to HTTP API with enhanced error handling
      return await this.performHTTPSearch(query, options);
    } catch (error: any) {
      console.error('❌ Real-time search failed:', error);
      this.state.update(s => ({
        ...s,
        error: `Search failed: ${error}`,
        isSearching: false,
      }));
      // Return fallback results
      return await this.getFallbackResults(query);
    } finally {
      const responseTime = Date.now() - startTime;
      this.updateSearchMetrics(responseTime);
    }
  }

  // Streaming search via WebSocket
  private async performStreamingSearch(query: string, options: any): Promise<SearchResult[]> {
    const promise = new Promise<SearchResult[]>((resolve, reject) => {
      const searchId = `search_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      const results: SearchResult[] = [];
      let searchCompleted = false;

      const messageHandler = (event: MessageEvent) => {
        try {
          const message = JSON.parse(event.data);
          if (message.searchId !== searchId) return;

          switch (message.type) {
            case 'search_result_chunk':
              const chunkResults = message.data.results || [];
              results.push(...chunkResults.map((r: any) => ({ ...r, realTime: true })));
              this.state.update(s => ({ ...s, results: [...results] }));
              break;
            case 'search_completed':
              searchCompleted = true;
              this.state.update(s => ({ ...s, isSearching: false, results }));
              resolve(results);
              break;
            case 'search_error':
              reject(new Error(message.data.error));
              break;
          }
        } catch (error: any) {
          console.error('❌ Error processing streaming search response:', error);
        }
      };

      this.ws!.addEventListener('message', messageHandler);

      this.ws!.send(
        JSON.stringify({
          type: 'real_time_search',
          searchId,
          query,
          options: {
            categories: options.categories || ['cases', 'evidence', 'documents'],
            vectorSearch: options.vectorSearch !== false,
            includeAI: options.includeAI !== false,
            streamResults: true,
            legalContext: {
              jurisdiction: 'federal',
              practiceAreas: 'all',
            },
          },
        })
      );

      const timeout = setTimeout(() => {
        if (!searchCompleted) {
          reject(new Error('Streaming search timeout'));
        }
      }, 30000); // 30 second timeout

      const cleanup = () => {
        clearTimeout(timeout);
        this.ws!.removeEventListener('message', messageHandler);
      };

      promise.finally(cleanup);
    });

    return promise;
  }

  // HTTP fallback search
  private async performHTTPSearch(query: string, options: any): Promise<SearchResult[]> {
    const searchParams = new URLSearchParams({
      q: query,
      categories: (options.categories || ['cases', 'evidence', 'documents']).join(','),
      vectorSearch: String(options.vectorSearch !== false),
      aiSuggestions: String(options.includeAI !== false),
      limit: '20',
    });
    // Try multiple endpoints with fallback
    const endpoints = [
      `/api/search/legal?${searchParams}`,
      `http://localhost:8094/search?${searchParams}`,
      `http://localhost:8093/search?${searchParams}`,
    ];
    let lastError: Error | null = null;
    for (const endpoint of endpoints) {
      try {
        const response = await fetch(endpoint, {
          method: 'GET',
          headers: { 'Content-Type': 'application/json' },
        });
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }
        const data = await response.json();
        const results = data.results || [];
        this.state.update(s => ({ ...s, results, isSearching: false }));
        return results;
      } catch (error: any) {
        console.warn(`❌ Endpoint ${endpoint} failed:`, error);
        lastError = error as Error;
        continue;
      }
    }
    throw lastError || new Error('All search endpoints failed');
  }

  // Handle streaming search results
  private handleSearchResults(data: any): void {
    const results = Array.isArray(data) ? data : data.results || [];
    this.state.update(s => ({ ...s, results, isSearching: false }));
  }

  // Handle search suggestions
  private handleSearchSuggestions(data: any): void {
    const suggestions = Array.isArray(data) ? data : data.suggestions || [];
    this.state.update(s => ({ ...s, suggestions }));
  }

  // Handle search progress updates
  private handleSearchProgress(data: any): void {
    console.log('🔄 Search progress:', data);
  }

  // Handle search errors
  private handleSearchError(data: any): void {
    const error = data.error || data.message || 'Unknown search error';
    this.state.update(s => ({ ...s, error, isSearching: false }));
  }

  // Update search metrics
  private updateSearchMetrics(responseTime: number): void {
    this.state.update(s => {
      const newTotalQueries = s.searchMetrics.totalQueries + 1;
      const newAverageTime =
        (s.searchMetrics.averageResponseTime * s.searchMetrics.totalQueries + responseTime) / newTotalQueries;
      return {
        ...s,
        searchMetrics: {
          totalQueries: newTotalQueries,
          averageResponseTime: Math.round(newAverageTime),
          lastQueryTime: responseTime,
        },
      };
    });
  }

  // Reconnection logic with exponential backoff
  private scheduleReconnection(): void {
    // Don't reconnect if we've exceeded max attempts
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.warn(
        `⚠️ Max WebSocket reconnection attempts (${this.maxReconnectAttempts}) reached. Switching to HTTP-only mode.`
      );
      this.state.update(s => ({
        ...s,
        error: 'Real-time connection unavailable - using standard search',
        connectionStatus: 'error',
      }));
      return;
    }

    this.reconnectAttempts++;

    // Exponential backoff: 2s, 4s, 8s, 16s, 32s
    const backoffDelay = this.reconnectInterval * Math.pow(2, this.reconnectAttempts - 1);

    console.log(
      `🔄 Scheduling WebSocket reconnection attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts} in ${backoffDelay}ms`
    );

    setTimeout(async () => {
      try {
        await this.connectWebSocket();
        this.state.update(s => ({
          ...s,
          isConnected: true,
          connectionStatus: 'connected',
          error: null,
        }));
        console.log('✅ WebSocket reconnected successfully');
      } catch (error) {
        console.warn(`❌ Reconnection attempt ${this.reconnectAttempts} failed:`, error);
        // scheduleReconnection will be called by onclose handler if needed
      }
    }, backoffDelay);
  }

  // Get fallback results when all else fails
  private async getFallbackResults(query: string): Promise<SearchResult[]> {
    return [
      {
        id: `fallback-${Date.now()}`,
        title: `Fallback search: ${query}`,
        type: 'document' as const,
        content: `Fallback search result for "${query}". Real-time services are currently unavailable.`,
        score: 0.5,
        metadata: {
          date: new Date().toISOString(),
          status: 'fallback',
          tags: ['fallback', query.toLowerCase()],
        },
        createdAt: new Date().toISOString(),
        realTime: false,
      },
    ];
  }

  // Graceful cleanup with proper event handler removal
  public disconnect(): void {
    console.log('🔌 Disconnecting real-time search service...');

    // Close WebSocket connection gracefully
    if (this.ws) {
      try {
        // Remove event handlers to prevent reconnection attempts
        this.ws.onclose = null;
        this.ws.onerror = null;
        this.ws.onmessage = null;

        // Close with normal closure code
        if (this.ws.readyState === WebSocket.OPEN || this.ws.readyState === WebSocket.CONNECTING) {
          this.ws.close(1000, 'Component destroyed');
        }
      } catch (error) {
        console.warn('⚠️ Error during WebSocket cleanup:', error);
      } finally {
        this.ws = null;
      }
    }

    // Reset reconnection attempts
    this.reconnectAttempts = 0;

    // Update state
    this.state.update(s => ({
      ...s,
      isConnected: false,
      connectionStatus: 'disconnected',
      isSearching: false,
      error: null,
    }));

    console.log('✅ Real-time search service disconnected');
  }
}

// Global real-time search service instance
export const realTimeSearchService = new RealTimeSearchService();

// Enhanced search hooks for Svelte 5 components
export function useRealTimeSearch() {
  return {
    state: realTimeSearchService.state,
    isReady: realTimeSearchService.isReady,
    hasResults: realTimeSearchService.hasResults,
    searchStatus: realTimeSearchService.searchStatus,
    search: (query: string, options?: any) => realTimeSearchService.performRealTimeSearch(query, options),
    disconnect: () => realTimeSearchService.disconnect(),
  };
}
